style.css:
@-moz-document url-prefix("https://www.rolimons.com/") {
/* global rounding */
 *,
*::before,
*::after,
button,
.btn,
input,
textarea,
select,
.alert,
.card,
.value-stat-box,
.d-none > .img-responsive,
#filter-min,
#filter-max {
  border-radius: 10px !important;
}

/* cards */
.mix_item {
  border-radius: 10px !important;
  overflow: hidden;
}
.mix_item .item_card_img_container {
  border: 0;
}

/* square-only elements */
svg,
.navbar,
.system_item_tag_icon,
.shadow_md_35 .position-relative,
.shadow_md_35 .global_item_search_system_item_tag_icon,
.shadow_md_35 .d-flex > .global_item_search_stat_data,
.mix_item .item_card_img_container,
.mix_item .d-flex > .text-light,
#player_value,
#player_rap,
#history_chart_notice > svg,
.page_title_offsite_link_icon > svg,
.odd > td,
.dataTables_scrollHeadInner .sorting,
.dataTables_scrollHeadInner .sorting_disabled,
.swiper-slide-active .wishlist_slider_main_image_container,
.swiper-slide-next .wishlist_slider_main_image_container,
.wishlist_slider_card .wishlist_slider_main_image_container,
.pb-2 .std_item_card_img_bkgnd_gradient,
.odd .premium_icon,
.even .premium_icon,
#stats-pane-overview div > .d-flex .card-title {
  border-radius: 0 !important;
}

/* top rounded */
.shadow > .pt-2,
.bg-dark {
  border-radius: 10px 10px 0 0 !important;
}

/* bottom rounded */
.stats_box {
  border-radius: 0 0 10px 10px !important;
}

/* left rounded */
#global_player_search_textbox,
#global_item_search_textbox,
#inventory_search_textbox,
#catalog_search_textbox,
#trade_calculator_page_search_textbox,
#filter-category-dropdown,
.px-xl-2 {
  border-radius: 10px 0 0 10px !important;
}

/* right rounded */
#global_player_search_textbox_clear,
#global_item_search_textbox_clear,
#inventory_search_textbox_clear,
#catalog_search_textbox_clear,
#trade_calculator_page_search_textbox_clear,
#deal-custom-percentage,
.btn-light {
  border-radius: 0 10px 10px 0 !important;
}

/* deal badges */
.deal_bg_color_poor,
.deal_bg_color_uncommon,
.deal_bg_color_rare,
.deal_bg_color_epic {
  border-radius: 0 10px 0 0 !important;
}

/* special cases */
.global_player_search_mix_item .std_item_card_img_bkgnd_gradient {
  border-radius: 0 0 16px 10px !important;
}

.highcharts-label > .highcharts-label-box {
  border-radius: 10px !important;
}

.card,
.panel,
.box {
  box-shadow: 0 4px 16px rgba(0,0,0,0.5) !important;
}

.switch-slider {
  border-radius: 7px !important;
}

.highcharts-button-box {
  rx: 7 !important;
  ry: 7 !important;
}
.highcharts-label {
  rx: 7 !important;
  ry: 7 !important;
}

.highcharts-label > .highcharts-label-box {
  rx: 7 !important;
  ry: 7 !important;
}

.show > .site_navbar_item {
  border-radius: 0px !important;
}

.nav-item > .dropdown-menu {
  border-radius: 0 0 10px 10px !important;
}

#navbarTradingDropdown,
#navbarCatalogDropdown,
#navbarUgcDropdown,
#navbarPlayersDropdown,
#navbarGamesDropdown,
#navbarPlayerDropdown,
#navbarMoreFeaturesDropdown {
  border-radius: 0px !important;
}

.nav-item:nth-child(7) > .nav-link,
.nav-item:nth-child(8) > .nav-link,
.nav-item:nth-child(9) > .nav-link {
  border-radius: 0px !important;
}

.ml-xl-5 .active,
.ml-xl-5 > .nav-item:nth-child(2) > .nav-link,
.ml-xl-5 > .nav-item:nth-child(3) > .nav-link {
  border-radius: 0 0 10px 10px !important;
}

#history_chart_tab,
#value_chart_tab,
#copies_chart_tab,
#ownership_chart_tab,
#hoarding_chart_tab,
#bc_owner_table_tab_button > .nav-link,
#all_copies_table_tab_button > .nav-link,
#hoards_table_tab_button > .nav-link {
  border-radius: 10px 10px 0 0 !important;
}

.active > .page-link {
  border-radius: 0 !important;
  border-top: 1px solid #000;
  border-bottom: 1px solid #000;
  border-left: none;
  border-right: none;
}

.paginate_button > .page-link {
  border-radius: 0 !important;
  border-top: 1px solid #222;
  border-bottom: 1px solid #222;
  border-left: none;
  border-right: none;
}

#bc_owners_table_previous > .page-link {
  border-radius: 10px 0 0 10px !important;
  border-left: 1px solid #222 !important;
}

#bc_owners_table_next > .page-link {
  border-radius: 0 10px 10px 0 !important;
  border-right: 1px solid #222 !important;
}

#suggested-roblox-assets-slider > .swiper-wrapper,
#suggested-ugc-assets-slider > .swiper-wrapper,
.container-fluid:nth-child(15) .section_header,
.container-fluid:nth-child(17) .section_header,
.suggested-roblox-assets-slider-button-next,
.suggested-ugc-assets-slider-button-next {
  display: none;
}

.nav-item .dropdown-menu .nav-link {
  border-radius: 0 !important;
}

.nav-item .dropdown-menu .nav-link:last-child {
  border-radius: 0 0 10px 10px !important;
}

.highcharts-series-1 {
  stroke-linejoin: round;
  stroke-linecap: round;
}

#inventory_nav_link,
#catalog_nav_link,
#asking_nav_link {
  border-radius: 10px 10px 0 0 !important;
}

#inventory_management_page_search_textbox {
  border-radius: 10px 0 0 10px !important;
}

#inventory_management_page_search_textbox_clear {
  border-radius: 0 10px 10px 0 !important;
}

.px-0 > .position-relative {
  border-radius: 0 !important;
  border: none !important;
}

#asking_list_pane {
  border-radius: 0 0 10px 10px !important;
}

.shadow_md_15 > .trade_ad_header > .text-truncate {
  border-radius: 10px 10px 0 0 !important;
}

.shadow_md_15 .ad_creator_pfp {
  border-radius: 0 !important;
}

.highcharts-scrollbar-thumb,
g:nth-child(3) > .highcharts-scrollbar-button,
g:nth-child(4) > .highcharts-scrollbar-button {
  rx: 10 !important;
  ry: 10 !important;
}

#filter-category-dropdown {
  border-radius: 10px !important;
}

#search_textbox {
  border-radius: 10px 0 0 10px !important;
}

#search_textbox_clear {
  border-radius: 0 10px 10px 0 !important;
}

.d-flex > .dropdown-menu {
  border-radius: 0 0 10px 10px !important;
}

#deal-calculation-button-group > .btn:nth-child(1),
#projection-visibility-button-group > .btn:nth-child(1) {
  border-radius: 10px 0 0 10px !important;
}

#deal-calculation-button-group > .btn:nth-child(2),
#projection-visibility-button-group > .btn:nth-child(2) {
  border-radius: 0 10px 10px 0 !important;
}

#projection-visibility-button-group > .active,
#deal-calculation-button-group > .active {
  background-color: #0084dd !important;
}

.container-fluid .d-inline-block {
  border-radius: 10px !important;
}

[id^="filter-button-"][aria-pressed="true"] {
  background-color: #0084dd !important;
  border-color: #0084dd !important;
  color: white !important;
}

#request_tag_filter_modal .modal-header,
#offer_value_filter_modal .modal-header,
#request_value_filter_modal .modal-header {
  border-radius: 10px 10px 0 0 !important;
}

/* remove rounding from trade ad block */
.text-truncate.w-100.py-0.pl-2.my-auto.d-flex.justify-content-between.flex-wrap{
    border-radius: 0 !important;
}

#offer_robux_textbox,
#request_robux_textbox {
    background-color: #2b2e33 !important;
    color: white !important;
    border: 1px solid #555 !important;
}

.trade_ad_header {
    border-radius: 12px 12px 0 0 !important;
    overflow: hidden !important;
}
  .mix_item:hover {
      transform: translateY(-2px);
  
      border-color: rgba(80,160,255,0.35);
  
      box-shadow:
          0 10px 28px rgba(0,0,0,0.38);
  }
  
  .item_card_name {
      padding: 4px 1px 6px 12px;
  
      font-weight: 600;
      font-size: 15px;
  
      color: #f5f5f5;
  
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
  }
  
  .inventory_item_image {
      transition:
          transform 0.2s ease,
          filter 0.2s ease;
  }
  
  .mix_item:hover .inventory_item_image {
      transform: scale(1.15);
  }
  
  .rare_tag_icon {
      filter:
          drop-shadow(0 0 6px rgba(120,180,255,0.8))
          drop-shadow(0 0 12px rgba(120,180,255,0.4));
  }

button,
.btn {
    transition: background-color 0.2s ease, filter 0.2s ease, transform 0.2s ease;
}

.hold_tag_icon {
    animation: holdPulse 1.8s ease-in-out infinite;
}

@keyframes holdPulse {
    0% {
        transform: scale(1);
        opacity: 0.85;
        filter: brightness(1);
    }
    50% {
        transform: scale(1.12);
        opacity: 1;
        filter: brightness(1.2);
    }
    100% {
        transform: scale(1);
        opacity: 0.85;
        filter: brightness(1);
    }
}

/* smooth transition for all navbar items */
.navbar .nav-link,
.navbar .navbar_menu_item_inner {
  transition: background-color 0.1s ease, filter 0.1s ease, transform 0.1s ease;
}

/* hover state (smooth darken) */
.navbar .nav-link:hover,
.navbar .navbar_menu_item_inner:hover {
  background-color: rgba(7, 7, 7, 7);
  filter: brightness(0.92);
}

/* click / pressed state */
.navbar .nav-link:active,
.navbar .navbar_menu_item_inner:active {
  background-color: rgba(0, 0, 0, 0.18);
  filter: brightness(0.85);
  transform: scale(0.98);
}

/* keyboard focus (optional but nice) */
.navbar .nav-link:focus-visible,
.navbar .navbar_menu_item_inner:focus-visible {
  outline: none;
  background-color: rgba(0, 0, 0, 0.14);
}

#offer_robux_textbox {
  border-radius: 10px !important;
}

.mix_item::before,
.mix_item::after {
  background: transparent !important;
  box-shadow: none !important;
}

/* =========================
   ITEM SLOT BASE
========================= */

.position-relative {
    position: relative;
}

/* make sure hover animation is smooth */
.ad_item_img,
.system_item_tag_container_1,
.system_item_tag_container_2,
.system_item_tag_container_3,
.system_item_tag_container_4 {
    transition: transform 0.22s cubic-bezier(0.2, 0.8, 0.2, 1);
    will-change: transform;
}

/* =========================
   HOVER SCALE (OPTION 2)
   image + tags move together
========================= */

.position-relative:hover .ad_item_img {
    transform: scale(1.12);
}

/* make ALL tag containers scale with the image */
.position-relative:hover .system_item_tag_container_1,
.position-relative:hover .system_item_tag_container_2,
.position-relative:hover .system_item_tag_container_3,
.position-relative:hover .system_item_tag_container_4 {
    transform: scale(1.12);
}

/* =========================
   LAYERING FIX (RARE / PROJECTED TAGS)
========================= */

.system_item_tag_container_1,
.system_item_tag_container_2,
.system_item_tag_container_3,
.system_item_tag_container_4 {
    position: absolute;
    z-index: 5;
    pointer-events: none;
}

/* keep images below tags but above background */
.ad_item_img {
    position: relative;
    z-index: 1;
}

/* ensure hover item always sits above neighbors */
.position-relative:hover {
    z-index: 10;
}

/* =========================
   CONTAINER SAFETY
   prevents clipping on scale
========================= */

.d-flex.flex-nowrap,
.d-flex.flex-wrap {
    overflow: visible;
}

.modal-header {
    border-bottom-left-radius: 0 !important;
    border-bottom-right-radius: 0 !important;
}

@keyframes diamondGlow {
    0% {
        filter: drop-shadow(0 0 3px rgba(64, 169, 255, 0.6));
    }
    50% {
        filter: drop-shadow(0 0 10px rgba(64, 169, 255, 1))
                drop-shadow(0 0 18px rgba(64, 169, 255, 0.7));
    }
    100% {
        filter: drop-shadow(0 0 3px rgba(64, 169, 255, 0.6));
    }
}

.item_flag svg {
    animation: diamondGlow 2.2s ease-in-out infinite;
}

/* smooth base */
.row.bg-primary img.img-fluid {
  transition: transform 0.25s ease;
  will-change: transform;
}

/* hover pop */
.row.bg-primary img.img-fluid:hover {
  transform: scale(1.05);
}

/*wishlist*/
/* card hover effect (same vibe as mix_item) */
.wishlist_slider_card_container {
    transition: transform 0.2s ease, box-shadow 0.2s ease;
    border-radius: 10px;
}

.wishlist_slider_card:hover .wishlist_slider_card_container {
    transform: translateY(-2px);
    box-shadow: 0 10px 28px rgba(0,0,0,0.38);
}

/* image zoom on hover */
.wishlist_slider_card_main_image {
    transition: transform 0.2s ease, filter 0.2s ease;
}

.wishlist_slider_card:hover .wishlist_slider_card_main_image {
    transform: scale(1.12);
}

/* disable button */
button.btn[data-target*="modal-div"] {
  pointer-events: none !important;
  opacity: 0.45;
  filter: grayscale(1);
  cursor: not-allowed;
  position: relative;
  overflow: visible !important; /* key fix */
}
}
